#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;getline(cin,s);
int open=0,ans=0;
for(char c:s){
if(c=='(')++open;
else if(c==')'){if(open)--open;else ++ans;}}
printf("%d\n",ans+open);return 0;}

